"use strict";
import { useMorphoUserVaultPosition } from "hooks/morpho";
import { useSearchParams } from "react-router-dom";
import { useAccount } from "wagmi";
import { Flex, Text } from "ui/src";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { ChartContainer } from "../ChartProperties";
import YourTransactionTable from "./YourTransactionTable";
export default function YourPosition() {
  const [searchParams] = useSearchParams();
  const { address: userAddress } = useAccount();
  const chainId = UniverseChainId.Mainnet;
  const vaultAddress = searchParams.get("address");
  const { data: userPosition, isLoading } = useMorphoUserVaultPosition(vaultAddress ?? void 0, userAddress, chainId);
  const depositValue = userPosition?.assetsValueFormatted ?? "0";
  const depositNumber = Number(depositValue);
  const assetSymbol = userPosition?.assetSymbol ?? "USDC";
  const formatDeposit = () => {
    if (isLoading) return "...";
    if (depositNumber === 0) return "0.00";
    if (depositNumber < 0.01) return "< 0.01";
    return depositNumber.toFixed(2);
  };
  return <Flex>
      <ChartContainer>
        <Flex
    flexDirection="row"
    justifyContent="space-between"
    alignItems="flex-start"
    marginBottom="$spacing16"
    gap={"$gap16"}
    $md={{ flexDirection: "column" }}
  >
          <Text variant="body3" color="$neutral2">
            My Deposit ({assetSymbol})
          </Text>
        </Flex>

        <Text variant="heading2" $md={{ variant: "heading3" }}>
          {formatDeposit()}
        </Text>

        {!userAddress && <Text variant="body3" color="$neutral3" mt="$spacing8">
            Connect wallet to view your position
          </Text>}
      </ChartContainer>
      <Flex mt="$spacing24">
        <Text variant="body2" color="$neutral2" mb={"$gap16"}>
          Your Transactions
        </Text>
        <YourTransactionTable vaultAddress={vaultAddress ?? void 0} />
      </Flex>
    </Flex>;
}
